solution.js:
const input = document.querySelector("#query");
const items = document.querySelectorAll("li");
input.addEventListener("input", () => {
  const query = input.value.toLowerCase();
  items.forEach(item => {
    item.hidden = !item.textContent.toLowerCase().includes(query);
  });
});
